    width = len(grid[0])

    all_5s = [(r, c) for r in range(height) for c in range(width) if grid[r][c] == 5]

    if not all_5s:
        return []

    visited = set()
    components = []

    def bfs(sr, sc, grid):
        queue = [(sr, sc)]
        visited.add((sr, sc))
        comp = [(sr, sc)]

        while queue:
            r, c = queue.pop(0)
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < height and 0 <= nc < width:
                    if grid[nr][nc] == 5 and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        queue.append((nr, nc))
                        comp.append((nr, nc))
        return comp

    for r, c in all_5s:
        if (r, c) not in visited:
            comp = bfs(r, c, grid)
            components.append(comp)

    return components

def transform(grid):
    height = len(grid)
    width = len(grid[0])

    result = [row[:] for row in grid]

    # Interior fill: for each row, fill 0s between first and last 5
    for r in range(height):
        cols_with_5 = [c for c in range(width) if result[r][c] == 5]
        if cols_with_5:
            first_c, last_c = cols_with_5[0], cols_with_5[-1]
            for c in range(first_c + 1, last_c):
                if result[r][c] == 0:
                    result[r][c] = 2

    # Find connected components
    components = get_components_info(grid)

    if not components:
        return result

    # Determine bar rows and alignments
    bar_configs = []  # list of (bar_row, cmin, cmax)

    if len(components) == 1:
        comp = components[0]
        min_r = min(r for r, c_pos in comp)
        max_r = max(r for r, c_pos in comp)
        cmin = min(c for r, c in comp)
        cmax = max(c for r, c in comp)

        # Single component: alignment depends on max_row
        bar_row = min_r - 1
        if max_r <= 6:
            # Left-aligned: from 0 to (max_c - 1)
            for c in range(0, cmax):
                result[bar_row][c] = 2
            bar_configs.append((bar_row, 0, cmax - 1))
        else:
            # Right-aligned: from (min_c + 1) to edge
            for c in range(cmin + 1, width):
                result[bar_row][c] = 2
            bar_configs.append((bar_row, cmin + 1, width - 1))
    else:
        # Multiple components:
        # Sort by top row
        components.sort(key=lambda c: min(r for r, c_pos in c))

        for i, comp in enumerate(components):
            rmin = min(r for r, c_pos in comp)
            rmax = max(r for r, c_pos in comp)
            cmin = min(c for r, c in comp)
            cmax = max(c for r, c in comp)

            bar_row = rmin - 1
            if i == 0:
                # Top component: right-aligned
                for c in range(cmin + 1, width):
                    result[bar_row][c] = 2
            else:
                # Bottom component(s): left-aligned
                for c in range(0, cmax):
                    result[bar_row][c] = 2

    return result

